import {CATEGORIES,CURRENCIES,todayISO,addDays,daysBetween,money,parseAmount,purchaseReturnDate,purchaseWarrantyDate,effectiveStatus,validateState,makeDemoState} from './core.js';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const drawings={
  overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  purchases:'M4 7h16l1 14H3z M8 7V6a4 4 0 0 1 8 0v1',
  calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h.01 M12 14h.01 M16 14h.01 M8 18h.01 M12 18h.01',
  shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z m-4 10 3 3 5-6',
  settings:'m9 3-.5 3-2 1-2.5-1-2 3 2 2v2l-2 2 2 3 2.5-1 2 1 .5 3h4l.5-3 2-1 2.5 1 2-3-2-2v-2l2-2-2-3-2.5 1-2-1-.5-3Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
  arrow:'M4 12h15 m-5-5 5 5-5 5', down:'m7 10 5 5 5-5', plus:'M12 5v14 M5 12h14', close:'m6 6 12 12 M18 6 6 18',
  search:'m21 21-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',
  clock:'M12 8v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
  info:'M12 11v6 M12 7h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',
  check:'m5 12 4 4L19 6', return:'M5 9h11a5 5 0 0 1 0 10h-4 M9 5 5 9l4 4',
  more:'M5 12h.01 M12 12h.01 M19 12h.01', edit:'m15 4 5 5 M4 20l4-1L21 6l-4-4L4 15Z',
  trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',
  download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6', upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',
  receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2Z M8 7h8 M8 11h8 M8 15h5',
  headphones:'M4 14v-3a8 8 0 0 1 16 0v3 M4 12h3v8H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2 M20 12h-3v8h3a2 2 0 0 0 2-2v-4a2 2 0 0 0-2-2',
  shirt:'m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4a4 4 0 0 1-8 0Z',
  home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',
  drop:'M12 2s-7 8-7 13a7 7 0 0 0 14 0c0-5-7-13-7-13Z M8 15a4 4 0 0 0 4 4',
  ball:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M4 7l5 3 6-2 4-3 M9 10l-1 6-4 3 M8 16l7 2 4-3 M15 8l4 7 M15 18l-3 3',
  box:'m3 7 9-5 9 5-9 5Z M3 7v10l9 5 9-5V7 M12 12v10 M7 5l9 5',
  sparkle:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',
};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${drawings[name]||drawings.box}"/></svg>`;
const categoryDrawing={Electronics:'headphones',Clothing:'shirt',Home:'home',Beauty:'drop',Sports:'ball',Other:'box'};
const KEY='return-ready-v1';
const blankState=()=>({version:1,demo:false,settings:{currency:'USD',leadDays:7},purchases:[]});
let state,storageError='',loadError=false;
try{const raw=localStorage.getItem(KEY);state=raw?validateState(JSON.parse(raw)):makeDemoState();if(!raw)localStorage.setItem(KEY,JSON.stringify(state));}catch{state=blankState();storageError='Saved data could not be read. Your existing browser copy has not been overwritten. You can import a backup in preferences.';loadError=true;}
let page=location.hash.slice(1)||'overview',query='',statusFilter='all',categoryFilter='All',sort='deadline',warrantyFilter='active',timelineType='all',timelineRange='30';
let editingId=null,detailId=null,pendingImport=null,installEvent=null,toastTimeout,undoAction=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';loadError=false;return true;}catch{storageError='Your browser could not save these changes. They are available for this session; export a backup before closing the app.';return false;}}
function toast(message,undo=null){clearTimeout(toastTimeout);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),undo?8500:4500);}
function shortDate(date){return new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function longDate(date){return new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function daysTo(date){return daysBetween(todayISO(),date);}
function deadlineText(date){const days=daysTo(date);return days<0?`${Math.abs(days)}d ago`:days===0?'Ends today':days===1?'1 day left':`${days} days left`;}
function dateClass(date){const days=daysTo(date);return days<0?'expired':days<=state.settings.leadDays?'urgent':'active';}
function openPurchases(){return state.purchases.filter(p=>effectiveStatus(p)==='active');}
function upcomingReturns(){return openPurchases().slice().sort((a,b)=>purchaseReturnDate(a).localeCompare(purchaseReturnDate(b)));}
function closeReturns(){return upcomingReturns().filter(p=>daysTo(purchaseReturnDate(p))<=state.settings.leadDays);}
function warranties(){return state.purchases.filter(p=>p.status!=='returned'&&purchaseWarrantyDate(p));}
function catIcon(p){return `<span class="category-icon ${esc(p.category.toLowerCase())}">${icon(categoryDrawing[p.category])}</span>`;}
function statusChip(p){const status=effectiveStatus(p),date=purchaseReturnDate(p);return `<span class="deadline-chip ${status==='active'?dateClass(date):status}">${icon(status==='kept'?'check':status==='returned'?'return':'clock')}${status==='active'?deadlineText(date):status==='expired'?'Window ended':status==='kept'?'Kept':'Returned'}</span>`;}
function nav(){return [['overview','overview','Overview'],['purchases','purchases','Purchases'],['deadlines','calendar','Deadlines'],['warranties','shield','Warranties']];}
function shell(){
  $('#sidebar').innerHTML=`<a href="#overview" class="brand"><img src="assets/icon.svg" alt="">Return<span>Ready</span></a><div class="eyebrow">A LITTLE MORE CLARITY</div><nav class="side-nav" aria-label="Main navigation">${nav().map(([id,i,title])=>`<a href="#${id}" class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${title}${id==='purchases'?`<span class="nav-count">${state.purchases.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-divider"></div><a href="#settings" class="nav-link ${page==='settings'?'active':''}">${icon('settings')}Preferences</a><div class="side-bottom"><div class="side-stamp">${icon('receipt')}</div><h3>Keep the good.<br>Track the rest.</h3><p>A little order for your purchases.<br>A little space for everything else.</p></div><div class="side-tagline">Mindful buying. Made easier.</div>`;
  $('#topbar').innerHTML=`<span class="eyebrow">Less paperwork. More peace of mind.</span><a href="#overview" class="brand topbar-logo"><img src="assets/icon.svg" alt="">Return<span>Ready</span></a><div class="top-right"><span class="date-label">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span><button class="icon-btn" aria-label="Upcoming return deadlines" data-action="show-alerts">${icon('bell')}${closeReturns().length?'<span class="dot"></span>':''}</button><button class="top-profile" data-action="preferences" aria-label="Open preferences"><span class="avatar">RR</span><span class="profile-label">My collection</span>${icon('down')}</button></div>`;
  $('#mobile-nav').innerHTML=nav().map(([id,i,title])=>`<a href="#${id}" class="mobile-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${id==='overview'?'Home':title}</a>`).join('');
}
function heading(title,subtitle,add=true){return `<div class="page-head"><div><div class="eyebrow">YOUR PURCHASES, WELL LOOKED AFTER</div><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div>${add?`<button class="btn btn-primary" data-action="add">${icon('plus')}Add purchase</button>`:''}</div>`;}
function demoBar(){return state.demo?`<div class="demo-bar"><span>${icon('info')}You’re exploring example purchases. Your own collection starts fresh.</span><button data-action="start-fresh">Start my collection →</button></div>`:'';}
function empty(title,description,action='add',label='Add a purchase',i='purchases'){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${description}</p><button class="btn btn-primary" data-action="${action}">${icon(action==='add'?'plus':'arrow')}${label}</button></div>`;}
function purchaseRow(p,type='return'){const date=type==='warranty'?purchaseWarrantyDate(p):purchaseReturnDate(p);return `<button class="purchase-row" data-action="detail" data-id="${p.id}">${catIcon(p)}<span><span class="purchase-name">${esc(p.name)}</span><span class="purchase-meta">${esc(p.merchant)} · ${money(p.amount,p.currency)}</span></span><span class="row-end"><span class="deadline-chip ${dateClass(date)}">${icon(type==='warranty'?'shield':'clock')}${deadlineText(date)}</span><span class="due-note">${type==='warranty'?'Warranty':'Return'} · ${shortDate(date)}</span></span></button>`;}
function receiptArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 225 180"><circle cx="119" cy="92" r="75" fill="#e4d9e9" stroke="none"/><path d="m57 34 78-10 15 119-14-7-11 11-13-8-12 11-14-9-13 10Z" fill="#fffaf3" stroke="#e3d7e5" transform="rotate(-8 105 87)"/><g stroke="#d4c2dc" transform="rotate(-8 105 87)"><path d="m73 52 42-5m-40 17 54-6M78 82l35-4m-32 16 47-5m-45 19 22-3"/><path d="m118 108 13-2" stroke="#e8bc9c" stroke-width="3"/></g><circle cx="157" cy="112" r="30" fill="#efb18a" stroke="#f7d3ba" stroke-width="3"/><path d="m144 112 9 9 17-19" stroke="#fff6e9" stroke-width="4"/></svg><span class="hero-pill">A LITTLE AHEAD FEELS GOOD.</span></div>`;}
function decisionsChart(){const kept=state.purchases.filter(p=>p.status==='kept').length,returned=state.purchases.filter(p=>p.status==='returned').length,open=state.purchases.length-kept-returned,total=state.purchases.length;let offset=0;const parts=[[open,'#a78bb7'],[kept,'#b4c8b3'],[returned,'#eab590']];const segments=parts.map(([number,color])=>{const percent=total?number/total*100:0;const svg=`<circle cx="60" cy="60" r="48" fill="none" stroke="${color}" stroke-width="11" pathLength="100" stroke-dasharray="${percent} ${100-percent}" stroke-dashoffset="${-offset}"/>`;offset+=percent;return svg;}).join('');return `<div class="decision-panel"><h3>A little perspective</h3><div class="donut-wrap"><div class="donut-chart" role="img" aria-label="${total} purchases: ${open} undecided, ${kept} kept, ${returned} returned"><svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="48" fill="none" stroke="#f0eaf3" stroke-width="11"/>${segments}</svg><div class="donut-label"><strong>${total}</strong><span>IN YOUR COLLECTION</span></div></div><div class="legend"><div class="legend-row"><span class="legend-dot"></span>Undecided<strong>${open}</strong></div><div class="legend-row"><span class="legend-dot green"></span>Kept<strong>${kept}</strong></div><div class="legend-row"><span class="legend-dot peach"></span>Returned<strong>${returned}</strong></div></div></div><p class="decision-foot"><strong>Every purchase has its place.</strong> Mark decisions as you go to keep your collection clear.</p></div>`;}
function renderOverview(){const active=openPurchases(),currency=state.settings.currency,amount=active.filter(p=>p.currency===currency).reduce((sum,p)=>sum+p.amount,0),soon=closeReturns(),upcoming=upcomingReturns();return heading('Everything in its window.','A calmer home for the purchases you’re still thinking about.')+demoBar()+`<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE ORDER. A LOT OF RELIEF.</div><h2>Nothing slips<br>through the window.</h2><p>Return dates, warranty details, and decisions to make.<br>A little clarity, all in one place.</p><a class="text-link" href="#deadlines">See what’s coming up ${icon('arrow')}</a></div>${receiptArt()}</section><section class="stats" aria-label="Your collection at a glance"><div class="stat"><div class="stat-top"><span class="stat-title">Return windows open</span><span class="stat-icon">${icon('purchases')}</span></div><div class="stat-number">${active.length}</div><div class="stat-caption">Purchases still within their dates</div></div><div class="stat"><div class="stat-top"><span class="stat-title">A decision coming up</span><span class="stat-icon orange">${icon('clock')}</span></div><div class="stat-number">${soon.length}</div><div class="stat-caption">Within the next ${state.settings.leadDays} days</div></div><div class="stat money-stat"><div class="stat-top"><span class="stat-title">Worth keeping an eye on</span><span class="stat-icon green">${icon('receipt')}</span></div><div class="stat-number">${money(amount,currency)}</div><div class="stat-caption">Open windows · ${currency} purchases only</div></div></section><div class="dashboard-grid"><section><div class="section-head"><div><h2>Next on your radar</h2><p>A few dates worth a little attention.</p></div><a class="text-link" href="#deadlines">All dates ${icon('arrow')}</a></div>${upcoming.length?`<div class="panel">${upcoming.slice(0,4).map(p=>purchaseRow(p)).join('')}</div>`:empty(state.purchases.length?'All clear for now.':'A little room for clarity.',state.purchases.length?'No open return windows. Your collection and warranty details are always close by.':'Add a purchase and its return policy. We’ll help keep the important dates in view.')}</section><section><div class="section-head"><div><h2>Your collection</h2><p>Keep the good. Let the rest go.</p></div></div>${decisionsChart()}</section></div><aside class="tip">${icon('receipt')}<p><strong>A small habit that helps.</strong> Keep your packaging until you’ve decided, and add the order reference to your purchase notes.</p></aside>`;}
function filteredPurchases(){const clean=query.trim().toLowerCase();const list=state.purchases.filter(p=>(statusFilter==='all'||effectiveStatus(p)===statusFilter)&&(categoryFilter==='All'||p.category===categoryFilter)&&[p.name,p.merchant,p.orderRef,p.notes].some(value=>value.toLowerCase().includes(clean)));list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='recent'?b.purchaseDate.localeCompare(a.purchaseDate):sort==='amount'?(a.currency.localeCompare(b.currency)||b.amount-a.amount):purchaseReturnDate(a).localeCompare(purchaseReturnDate(b)));return list;}
function purchaseCard(p){const status=effectiveStatus(p),date=purchaseReturnDate(p);return `<article class="purchase-card"><div class="card-top">${catIcon(p)}${statusChip(p)}</div><h3>${esc(p.name)}</h3><p class="card-merchant">${esc(p.merchant)}</p><p class="card-price">${money(p.amount,p.currency)}</p><div class="deadline-box ${status==='active'?dateClass(date):status}"><span>${status==='kept'?'A keeper':status==='returned'?'Marked returned':'Return deadline'}</span><strong>${status==='kept'?'Kept & filed':status==='returned'?'Decision made':shortDate(date)}</strong></div><p class="card-note">Purchased ${shortDate(p.purchaseDate)}${p.warrantyMonths?` · ${p.warrantyMonths}-month warranty`:''}</p><div class="card-bottom"><button class="text-link" data-action="detail" data-id="${p.id}">Purchase details ${icon('arrow')}</button><button class="icon-btn" data-action="edit" data-id="${p.id}" aria-label="Edit ${esc(p.name)}">${icon('more')}</button></div></article>`;}
function renderPurchases(){const list=filteredPurchases();return heading('A place for every purchase.','All the details, without the drawer full of receipts.')+demoBar()+`<div class="tabs" role="group" aria-label="Purchase status">${[['all','All purchases'],['active','Window open'],['expired','Window ended'],['kept','Kept'],['returned','Returned']].map(([id,label])=>`<button class="tab ${statusFilter===id?'active':''}" aria-pressed="${statusFilter===id}" data-action="status-filter" data-value="${id}">${label}<span class="count">${state.purchases.filter(p=>id==='all'||effectiveStatus(p)===id).length}</span></button>`).join('')}</div><div class="filter-row"><div class="search-wrap">${icon('search')}<input id="purchase-search" class="input" aria-label="Search purchases" placeholder="Find an item, shop, or order reference…" value="${esc(query)}"></div><select id="category-filter" class="select" aria-label="Purchase category">${['All',...CATEGORIES].map(c=>`<option ${categoryFilter===c?'selected':''}>${c}</option>`).join('')}</select><select id="purchase-sort" class="select" aria-label="Sort purchases"><option value="deadline" ${sort==='deadline'?'selected':''}>Deadline first</option><option value="recent" ${sort==='recent'?'selected':''}>Recently purchased</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="amount" ${sort==='amount'?'selected':''}>Amount by currency</option></select></div><p class="result-caption">${list.length} ${list.length===1?'purchase':'purchases'}${sort==='amount'?' · Currencies are grouped separately; amounts are not converted.':''}</p>${list.length?`<div class="purchase-grid">${list.map(purchaseCard).join('')}</div>`:empty(query||statusFilter!=='all'||categoryFilter!=='All'?'Nothing in this corner.':'Your collection starts here.',query||statusFilter!=='all'||categoryFilter!=='All'?'Try a different search or filter, or add a new purchase.':'Add a purchase, set its return window, and keep its details close.')}`;}
function timelineEvents(){const events=[];for(const p of state.purchases){if(p.status==='returned')continue;if((timelineType==='all'||timelineType==='return')&&p.status==='active')events.push({p,date:purchaseReturnDate(p),type:'return'});const warranty=purchaseWarrantyDate(p);if((timelineType==='all'||timelineType==='warranty')&&warranty)events.push({p,date:warranty,type:'warranty'});}return events.filter(e=>timelineRange==='all'||daysTo(e.date)<=Number(timelineRange)).sort((a,b)=>a.date.localeCompare(b.date));}
function renderDeadlines(){const events=timelineEvents(),groups=[['Past dates',e=>daysTo(e.date)<0],['Today',e=>daysTo(e.date)===0],['The next 7 days',e=>daysTo(e.date)>0&&daysTo(e.date)<=7],['A little further ahead',e=>daysTo(e.date)>7]];return heading('A little ahead of the date.','The important windows, neatly in order.',false)+`<div class="filter-row"><div class="tabs" style="margin-bottom:0" role="group" aria-label="Deadline type">${[['all','All dates'],['return','Return windows'],['warranty','Warranties']].map(([id,label])=>`<button class="tab ${timelineType===id?'active':''}" aria-pressed="${timelineType===id}" data-action="timeline-type" data-value="${id}">${label}</button>`).join('')}</div><select id="timeline-range" class="select" aria-label="Deadline range"><option value="30" ${timelineRange==='30'?'selected':''}>Next 30 days + past dates</option><option value="90" ${timelineRange==='90'?'selected':''}>Next 90 days + past dates</option><option value="all" ${timelineRange==='all'?'selected':''}>All dates</option></select></div><p class="result-caption">${events.length} ${events.length===1?'date':'dates'} · Dates follow the return and warranty information you enter.</p><div class="timeline-layout"><section>${events.length?groups.map(([title,predicate])=>{const group=events.filter(predicate);return group.length?`<section class="timeline-group"><h2 class="timeline-group-label">${title} · ${group.length}</h2><div class="panel">${group.map(e=>purchaseRow(e.p,e.type)).join('')}</div></section>`:'';}).join(''):empty('A clear little horizon.','No dates match this view. Add a purchase or choose a longer date range.','add','Add purchase','calendar')}</section><aside class="timeline-side">${icon('calendar')}<h2>Dates don’t<br>have to be a worry.</h2><p>Make decisions before the last day. Your reminder lead time is set to <strong>${state.settings.leadDays} days</strong>.</p><button class="btn btn-outline" data-action="preferences">${icon('settings')}Set my preferences</button></aside></div>`;}
function renderWarranties(){const list=warranties().filter(p=>warrantyFilter==='all'||(warrantyFilter==='active'?daysTo(purchaseWarrantyDate(p))>=0:daysTo(purchaseWarrantyDate(p))<0)).sort((a,b)=>purchaseWarrantyDate(a).localeCompare(purchaseWarrantyDate(b)));return heading('A little longer peace of mind.','Keep your warranty details close, long after the return window.',false)+`<div class="info-banner">${icon('info')}Warranty dates use the lengths you enter. Keep the original terms and proof of purchase; coverage depends on the seller or manufacturer.</div><div class="tabs" role="group" aria-label="Warranty status">${[['active','In date'],['expired','Date passed'],['all','All warranties']].map(([id,title])=>`<button class="tab ${warrantyFilter===id?'active':''}" data-action="warranty-filter" data-value="${id}" aria-pressed="${warrantyFilter===id}">${title}</button>`).join('')}</div><p class="result-caption">${list.length} ${list.length===1?'warranty':'warranties'} · Returned purchases are excluded.</p>${list.length?`<div class="warranty-grid">${list.map(p=>{const date=purchaseWarrantyDate(p),days=daysTo(date),total=Math.max(1,daysBetween(p.purchaseDate,date)),percent=Math.min(100,Math.max(0,days/total*100));return `<article class="warranty-card ${days<0?'expired':''}"><div class="warranty-top">${catIcon(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.merchant)} · ${p.warrantyMonths} months</p></div>${icon('shield','warranty-icon')}</div><div class="warranty-data"><div><span>Purchased</span><strong>${longDate(p.purchaseDate)}</strong></div><div><span>Warranty end date</span><strong>${longDate(date)}</strong></div></div><div class="progress-track" role="meter" aria-label="Warranty time remaining" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent)}"><span style="width:${percent}%"></span></div><div class="warranty-foot"><span>${days<0?'Date passed':days===0?'Ends today':`${days} days remaining`}</span><button class="text-link" data-action="detail" data-id="${p.id}">View details ${icon('arrow')}</button></div></article>`;}).join('')}</div>`:empty('Space for a little reassurance.','Add a warranty length when recording a purchase. Its dates and details will appear here.','add','Add purchase','shield')}`;}
function renderSettings(){return heading('Make a little room for you.','A few preferences for a calmer collection.',false)+`<div class="settings-layout"><section class="settings-card"><h2>Your everyday defaults</h2><p>New purchases start with these choices. Existing purchase amounts stay as entered.</p><div class="setting-row"><div><h3>Default currency</h3><p>Used for new purchases and the overview value. Amounts in other currencies stay separate.</p></div><select id="currency-setting" class="select" aria-label="Default currency">${CURRENCIES.map(c=>`<option ${state.settings.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="setting-row"><div><h3>A little heads-up</h3><p>Flag open return windows this many days before the deadline.</p></div><select id="lead-setting" class="select" aria-label="Reminder lead time">${[0,1,3,5,7,14,30].map(d=>`<option value="${d}" ${state.settings.leadDays===d?'selected':''}>${d===0?'On the day':`${d} ${d===1?'day':'days'} before`}</option>`).join('')}</select></div><p class="inline-note">Reminders appear in the app. Background push notifications are not enabled.</p></section><section class="settings-card"><h2>Your collection, in your hands</h2><p>Export a backup or move an existing ReturnReady file onto this device. Imports replace the current collection after you confirm.</p><div class="settings-actions"><button class="btn btn-outline" data-action="export">${icon('download')}Export backup</button><button class="btn btn-outline" data-action="import">${icon('upload')}Import backup</button><button class="btn btn-light" data-action="install">${icon('purchases')}Install app</button></div><div class="data-note">${icon('info')}Your purchases are saved in this browser on this device. There is no account sync, merchant connection, or cloud receipt storage.</div></section><section class="settings-card"><h2>A fresh little start</h2><p>${state.demo?'You’re viewing example purchases. Start a personal collection when you’re ready.':'Clear your collection, or explore the example purchases. Export first if you want to keep a backup.'}</p><div class="settings-actions"><button class="btn btn-light" data-action="load-demo">Explore sample collection</button><button class="btn btn-danger" data-action="clear-data">${icon('trash')}Clear collection</button></div></section><section class="settings-card"><div class="about-logo"><img src="assets/icon.svg" alt=""><div><h3>ReturnReady</h3><p>KEEP THE GOOD. TRACK THE REST.</p></div></div><p>Made for the small dates that can make a big difference. Return windows are based on the policies you enter, and may not reflect every condition of a store’s policy.</p></section></div>`;}
function render(){if(!['overview','purchases','deadlines','warranties','settings'].includes(page))page='overview';shell();$('#main').innerHTML=(storageError?`<div class="storage-warning">${esc(storageError)}</div>`:'')+({overview:renderOverview,purchases:renderPurchases,deadlines:renderDeadlines,warranties:renderWarranties,settings:renderSettings}[page])();}
function go(target){if(page===target){render();window.scrollTo(0,0);}else location.hash=target;}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render();window.scrollTo({top:0,behavior:'instant'});});
function dialog(title,body){$('#dialog').innerHTML=`<div class="dialog-top"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function showPurchaseForm(id=null){const p=id?state.purchases.find(p=>p.id===id):null;editingId=p?.id||null;const isExact=Boolean(p?.returnDeadline);dialog(p?'A little update.':'Something worth tracking.',`<p class="dialog-intro">Keep the details close. We’ll keep the dates in view.${state.demo&&!p?' Adding your first purchase replaces the sample collection.':''}</p><form id="purchase-form"><label class="field"><span>What did you buy?</span><input class="input" name="name" placeholder="e.g. Wireless headphones" maxlength="120" value="${esc(p?.name||'')}" required></label><div class="form-row"><label class="field"><span>Where from?</span><input class="input" name="merchant" placeholder="Shop or seller" maxlength="120" value="${esc(p?.merchant||'')}" required></label><label class="field"><span>Category</span><select name="category" class="select">${CATEGORIES.map(c=>`<option ${(p?.category||'Other')===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="form-row"><label class="field"><span>Amount paid</span><input class="input" name="amount" inputmode="decimal" placeholder="0.00" value="${p?(p.amount/100).toFixed(2):''}" required pattern="(?:[0-9]+(?:\\.[0-9]{0,2})?|\\.[0-9]{1,2})" title="Enter an amount with up to two decimal places."></label><label class="field"><span>Currency</span><select name="currency" class="select">${CURRENCIES.map(c=>`<option ${(p?.currency||state.settings.currency)===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="form-row"><label class="field"><span>Purchase date</span><input class="input" name="purchaseDate" type="date" min="2000-01-01" max="2100-12-31" value="${p?.purchaseDate||todayISO()}" required></label><label class="field"><span>Warranty in months (optional)</span><input class="input" name="warrantyMonths" type="number" min="0" max="120" step="1" value="${p?.warrantyMonths||0}"></label></div><span class="field-label">How would you like to set the return window?</span><div class="segmented" role="group" aria-label="Return deadline method"><button type="button" class="${!isExact?'active':''}" data-action="return-mode" data-value="days" aria-pressed="${!isExact}">Number of days</button><button type="button" class="${isExact?'active':''}" data-action="return-mode" data-value="exact" aria-pressed="${isExact}">An exact deadline</button></div><input type="hidden" name="returnMode" value="${isExact?'exact':'days'}"><label class="field" id="return-days-field" ${isExact?'hidden':''}><span>Days after the purchase date</span><input class="input" name="returnDays" type="number" min="0" max="730" step="1" value="${p?.returnDays??30}" ${isExact?'disabled':''} required><small>Enter the store’s policy. If the receipt gives a specific last date, use an exact deadline.</small></label><label class="field" id="return-exact-field" ${!isExact?'hidden':''}><span>Last date for return</span><input class="input" name="returnDeadline" type="date" min="${p?.purchaseDate||todayISO()}" max="2100-12-31" value="${p?.returnDeadline||purchaseReturnDate(p||{purchaseDate:todayISO(),returnDays:30})}" ${!isExact?'disabled':''} required></label><div class="date-preview"><span>Your return window</span><strong id="return-preview"></strong></div><label class="field"><span>Order or receipt reference (optional)</span><input class="input" name="orderRef" placeholder="An order number to find later" maxlength="150" value="${esc(p?.orderRef||'')}"></label><label class="field"><span>A little note (optional)</span><textarea class="input" name="notes" placeholder="Receipt location, policy details, or what to try before deciding…" maxlength="3000" rows="3">${esc(p?.notes||'')}</textarea></label><div id="form-error" class="form-error" role="alert" hidden></div><div class="form-actions"><button type="button" class="btn btn-outline" data-action="close">Cancel</button><button type="submit" class="btn btn-primary">${icon(p?'check':'plus')}${p?'Save changes':'Add to my collection'}</button></div></form>`);updateReturnPreview();setTimeout(()=>$('#purchase-form [name="name"]')?.focus(),50);}
function updateReturnPreview(){const form=$('#purchase-form');if(!form)return;const date=form.elements.purchaseDate.value,exact=form.elements.returnMode.value==='exact';form.elements.returnDeadline.min=date||'2000-01-01';try{if(!date)throw new Error();const result=exact?form.elements.returnDeadline.value:addDays(date,Number(form.elements.returnDays.value));if(exact&&daysBetween(date,result)<0)throw new Error();$('#return-preview').textContent=`${longDate(result)} · ${deadlineText(result)}`;}catch{$('#return-preview').textContent='Choose a valid date';}}
function submitPurchase(form){if(!form.reportValidity())return;try{const data=new FormData(form),previous=editingId?state.purchases.find(p=>p.id===editingId):null;const p={id:editingId||crypto.randomUUID(),name:data.get('name'),merchant:data.get('merchant'),amount:parseAmount(data.get('amount')),currency:data.get('currency'),purchaseDate:data.get('purchaseDate'),returnDays:data.get('returnMode')==='exact'?(previous?.returnDays??30):Number(form.elements.returnDays.value),returnDeadline:data.get('returnMode')==='exact'?data.get('returnDeadline'):null,warrantyMonths:Number(data.get('warrantyMonths')||0),category:data.get('category'),status:previous?.status||'active',orderRef:data.get('orderRef'),notes:data.get('notes'),createdAt:previous?.createdAt||new Date().toISOString()};const isFirstPersonal=state.demo&&!previous,candidate={...state,demo:isFirstPersonal?false:state.demo,purchases:isFirstPersonal?[p]:previous?state.purchases.map(item=>item.id===previous.id?p:item):[...state.purchases,p]};state=validateState(candidate);save();closeDialog();render();toast(previous?'Purchase details updated.':`${p.name.trim()} is now in your collection.`);}catch(error){$('#form-error').textContent=error.message||'Please check the purchase details.';$('#form-error').hidden=false;}}
function detailDialog(id){const p=state.purchases.find(p=>p.id===id);if(!p)return;detailId=id;const status=effectiveStatus(p),warranty=purchaseWarrantyDate(p);dialog('A place for the details.',`<div class="detail-heading">${catIcon(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.merchant)} · ${esc(p.category)}</p></div></div><p class="detail-price">${money(p.amount,p.currency)}</p><div class="detail-status">${statusChip(p)}</div><div class="detail-grid"><div><span>Purchase date</span><strong>${longDate(p.purchaseDate)}</strong></div><div><span>Return deadline</span><strong>${longDate(purchaseReturnDate(p))}</strong></div><div><span>Return window entered</span><strong>${p.returnDeadline?'Exact date':`${p.returnDays} days after purchase`}</strong></div><div><span>Warranty end date</span><strong>${warranty?`${longDate(warranty)} (${p.warrantyMonths} months)`:'No warranty entered'}</strong></div><div><span>Order / receipt reference</span><strong>${esc(p.orderRef||'Not added')}</strong></div><div><span>Your decision</span><strong>${status==='kept'?'Kept':status==='returned'?'Marked returned':'Undecided'}</strong></div></div>${p.notes?`<section class="detail-notes"><h3>A little note</h3><p>${esc(p.notes)}</p></section>`:''}<div class="detail-actions"><button class="btn btn-outline" data-action="edit" data-id="${id}">${icon('edit')}Edit details</button>${p.status==='active'?`<button class="btn btn-light" data-action="change-status" data-value="kept" data-id="${id}">${icon('check')}Keep it</button><button class="btn btn-light" data-action="change-status" data-value="returned" data-id="${id}">${icon('return')}Returned</button>`:`<button class="btn btn-light" data-action="change-status" data-value="active" data-id="${id}">${icon('return')}Reopen decision</button>`}<button class="btn btn-danger" data-action="delete-purchase" data-id="${id}" aria-label="Delete purchase">${icon('trash')}</button></div><p class="inline-note">Dates reflect the information you entered. A date in this app does not confirm eligibility under a store’s return or warranty policy.</p>`);}
function changeStatus(id,status){const p=state.purchases.find(p=>p.id===id);if(!p)return;const old=p.status;p.status=status;save();render();detailDialog(id);toast(status==='kept'?'A keeper. Decision saved.':status==='returned'?'Purchase marked returned.':'Decision reopened.',()=>{p.status=old;save();render();if($('#dialog').open)detailDialog(id);toast('Previous decision restored.');});}
function deletePurchase(id){const index=state.purchases.findIndex(p=>p.id===id);if(index<0)return;const [purchase]=state.purchases.splice(index,1);save();closeDialog();render();toast('Purchase removed from your collection.',()=>{state.purchases.splice(Math.min(index,state.purchases.length),0,purchase);save();render();toast('Purchase restored.');});}
function confirmation(title,text,action,label){dialog(title,`<p class="dialog-intro">${text}</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Keep my collection</button><button class="btn btn-primary" data-action="${action}">${label}</button></div>`);}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`return-ready-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your collection backup is ready.');}
function alertsDialog(){const soon=closeReturns();dialog('A little heads-up.',`<p class="dialog-intro">Open return windows ending within ${state.settings.leadDays} days. These dates use the policies you entered.</p>${soon.length?`<div class="panel">${soon.map(p=>purchaseRow(p)).join('')}</div>`:`<div class="empty">${icon('check')}<h3>All clear for now.</h3><p>No open return windows need attention in this time period.</p></div>`}<p class="inline-note">Past dates remain visible in Deadlines. In-app reminders don’t run as background phone notifications.</p>`);}
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const{action,id,value}=button.dataset;
  if(action==='close')closeDialog();
  else if(action==='add')showPurchaseForm();
  else if(action==='edit')showPurchaseForm(id);
  else if(action==='detail')detailDialog(id);
  else if(action==='preferences'){closeDialog();go('settings');}
  else if(action==='show-alerts')alertsDialog();
  else if(action==='status-filter'){statusFilter=value;render();}
  else if(action==='warranty-filter'){warrantyFilter=value;render();}
  else if(action==='timeline-type'){timelineType=value;render();}
  else if(action==='return-mode'){const form=$('#purchase-form'),exact=value==='exact';form.elements.returnMode.value=value;form.elements.returnDays.disabled=exact;form.elements.returnDeadline.disabled=!exact;$('#return-days-field').hidden=exact;$('#return-exact-field').hidden=!exact;form.querySelectorAll('[data-action="return-mode"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===value);b.setAttribute('aria-pressed',String(b.dataset.value===value));});updateReturnPreview();}
  else if(action==='change-status')changeStatus(id,value);
  else if(action==='delete-purchase')deletePurchase(id);
  else if(action==='undo'){if(undoAction){const fn=undoAction;undoAction=null;fn();}}
  else if(action==='export')exportData();
  else if(action==='import'){$('#import-file').value='';$('#import-file').click();}
  else if(action==='confirm-import'){if(!pendingImport)return;state=pendingImport;pendingImport=null;save();closeDialog();go('overview');toast('Your backup has been imported.');}
  else if(action==='start-fresh'){confirmation('A fresh little start.','This replaces example purchases with your own empty collection. Your preferences stay the same.','confirm-fresh','Start my collection');}
  else if(action==='confirm-fresh'){state={...blankState(),settings:{...state.settings}};save();closeDialog();go('overview');showPurchaseForm();}
  else if(action==='load-demo'){confirmation('Explore the examples?','This replaces the current purchases with example data. Export a backup first if you want to keep your collection.','confirm-demo','Load sample collection');}
  else if(action==='confirm-demo'){state=makeDemoState();save();closeDialog();go('overview');toast('You’re exploring example purchases.');}
  else if(action==='clear-data'){confirmation('Clear this collection?','This removes purchases and resets preferences on this device. Export a backup first if you want to keep your data.','confirm-clear','Clear collection');}
  else if(action==='confirm-clear'){state=blankState();save();closeDialog();go('overview');toast('Your collection has been cleared.');}
  else if(action==='install'){if(installEvent){await installEvent.prompt();installEvent=null;}else dialog('A little closer at hand.',`<p class="dialog-intro">You can add ReturnReady to your home screen using your browser’s menu.</p><div class="import-preview"><strong>iPhone or iPad:</strong> Open in Safari, tap Share, then Add to Home Screen.<br><br><strong>Android:</strong> Open the browser menu and look for Install app or Add to Home screen.<br><br><strong>Desktop:</strong> Use your browser’s install icon when available.</div><p class="inline-note">Installation support depends on your browser. Purchases stay stored in that browser on this device.</p>`);}
});
document.addEventListener('submit',event=>{if(event.target.id==='purchase-form'){event.preventDefault();submitPurchase(event.target);}});
document.addEventListener('input',event=>{if(event.target.id==='purchase-search'){query=event.target.value;const cursor=event.target.selectionStart;render();$('#purchase-search')?.focus();$('#purchase-search')?.setSelectionRange(cursor,cursor);}if(event.target.closest('#purchase-form')&&['purchaseDate','returnDays','returnDeadline'].includes(event.target.name))updateReturnPreview();});
document.addEventListener('change',async event=>{const el=event.target;
  if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('Choose a JSON backup smaller than 5 MB.');pendingImport=validateState(JSON.parse(await file.text()));dialog('A familiar collection.',`<p class="dialog-intro">This backup is ready to import. It will replace the purchases and preferences currently on this device.</p><div class="import-preview"><strong>${pendingImport.purchases.length} purchases</strong><br>Default currency: ${pendingImport.settings.currency}<br>Contains ${pendingImport.demo?'example':'personal'} data</div><div class="form-actions"><button class="btn btn-outline" data-action="close">Cancel</button><button class="btn btn-primary" data-action="confirm-import">Import collection</button></div>`);}catch(error){pendingImport=null;dialog('Let’s check that file.',`<p class="dialog-intro">${esc(error.message||'This backup could not be read. Choose a valid ReturnReady JSON export.')}</p><button class="btn btn-primary full-width" data-action="close">Back to my collection</button>`);}return;}
  if(el.id==='category-filter')categoryFilter=el.value;else if(el.id==='purchase-sort')sort=el.value;else if(el.id==='timeline-range')timelineRange=el.value;else if(el.id==='currency-setting')state.settings.currency=el.value;else if(el.id==='lead-setting')state.settings.leadDays=Number(el.value);else return;save();render();
});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const bounds=$('#dialog').getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)closeDialog();}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installEvent=event;});
window.addEventListener('appinstalled',()=>{installEvent=null;toast('ReturnReady is ready on your home screen.');});
let lastToday=todayISO();setInterval(()=>{if(todayISO()!==lastToday){lastToday=todayISO();render();}},60000);
render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
